"""Offline Google-inspired training UI; contains no external assets or scripts."""
import html

CSS = '''
*{box-sizing:border-box}body{margin:0;color:#202124;background:#f6f8fc;font:14px/1.5 Arial,Helvetica,sans-serif}a{color:#0b57d0;text-decoration:none}a:hover{text-decoration:underline}button,.button{background:#0b57d0;color:white;border:0;border-radius:24px;padding:12px 25px;font:600 14px Arial;cursor:pointer;display:inline-block;text-decoration:none}button:hover,.button:hover{background:#0847ae;text-decoration:none}a:focus-visible,button:focus-visible,input:focus-visible{outline:3px solid #669df6;outline-offset:3px}.training{background:#fff3cd;color:#584615;padding:9px 24px;text-align:center;font-size:12px;border-bottom:1px solid #eadba9}.training strong{letter-spacing:.7px}.training a{margin-left:14px;color:#584615;text-decoration:underline}.topbar{height:76px;display:flex;align-items:center;gap:24px;padding:0 26px}.hamb{font-size:23px;color:#5f6368}.brand{display:flex;align-items:center;gap:12px;min-width:184px;font-size:26px;color:#5f6368}.mailmark{font-size:36px;font-weight:bold;color:#ea4335;line-height:1}.search{background:#eaf1fb;border-radius:28px;max-width:700px;flex:1;padding:14px 22px;font-size:16px;color:#52606c}.avatar{width:34px;height:34px;border-radius:50%;background:#7e57c2;color:white;display:grid;place-items:center;flex-shrink:0}.topright{margin-left:auto;display:flex;gap:22px;align-items:center;font-size:22px;color:#5f6368}.mail-layout{display:grid;grid-template-columns:240px 1fr;padding:0 18px 24px 0;min-height:calc(100vh - 113px)}aside{padding:0 12px}.compose{background:#c2e7ff;border-radius:16px;padding:19px 22px;display:inline-block;margin:6px 0 18px 4px;font-size:14px;color:#001d35}.folder{display:flex;gap:18px;padding:8px 18px;border-radius:0 24px 24px 0;color:#444746}.folder b{margin-left:auto}.folder.active{background:#d3e3fd;color:#001d35;font-weight:bold}.labels{margin:30px 18px;color:#444746;font-size:15px}.mailpane{background:white;border-radius:18px;overflow:hidden}.toolbar{height:57px;display:flex;gap:28px;align-items:center;padding:0 25px;color:#62676c;border-bottom:1px solid #f1f3f4}.toolbar .right{margin-left:auto;font-size:12px}.message{padding:25px 42px 50px 30px}.subject{font-size:24px;font-weight:400;margin:0 0 27px 42px;line-height:1.4}.pill{font-size:11px;background:#e8eaed;border-radius:4px;padding:3px 7px;vertical-align:middle;margin-left:12px}.sender{display:flex;gap:13px;align-items:center}.sender strong{font-size:14px}.sender small,.muted{color:#5f6368}.sender .time{margin-left:auto;font-size:12px;color:#5f6368}.email-body{max-width:650px;margin:35px auto}.share-card{border:1px solid #dadce0;border-radius:10px;padding:32px}.share-card h2{font-size:23px;font-weight:400;margin:0 0 27px}.file-row{display:flex;align-items:center;gap:14px;border:1px solid #dadce0;border-radius:6px;padding:14px;margin:25px 0}.doc-icon{background:#4285f4;border-radius:3px;color:white;font-size:12px;font-weight:bold;padding:12px 7px}.smallprint{font-size:12px;color:#70757a;margin-top:24px}.reply{display:inline-block;margin-top:35px;border:1px solid #dadce0;border-radius:24px;padding:8px 22px;color:#5f6368}.g-word{font-size:27px;letter-spacing:-1px;font-weight:500}.g-word span:nth-child(1),.g-word span:nth-child(4){color:#4285f4}.g-word span:nth-child(2),.g-word span:nth-child(6){color:#ea4335}.g-word span:nth-child(3){color:#fbbc05}.g-word span:nth-child(5){color:#34a853}.auth-wrap{max-width:1040px;margin:100px auto 0;padding:0 24px}.auth-card{background:white;border-radius:28px;padding:40px;min-height:385px}.auth-grid{display:grid;grid-template-columns:1fr 1fr;gap:60px;margin-top:22px}.auth-grid h1{font-size:36px;font-weight:400;line-height:1.2;margin:0 0 20px}.auth-grid p{font-size:16px}.account{display:inline-block;border:1px solid #dadce0;border-radius:20px;padding:6px 13px;font-size:13px}.auth-fields{padding-top:3px}label{display:block;font-size:13px;color:#444746}input{width:100%;font-size:16px;padding:17px 14px;border:1px solid #747775;border-radius:4px;margin:5px 0 18px;background:white;color:#202124}input:focus{outline:2px solid #0b57d0;border-color:transparent}.auth-fields button{float:right;margin-top:18px}.auth-fields form:after{content:'';display:block;clear:both}.error{color:#b3261e;font-size:13px}.demo-hint{font-size:12px!important;background:#f0f4f9;padding:12px;border-radius:8px;color:#444746}.auth-footer{display:flex;justify-content:space-between;margin:20px 15px;font-size:12px;color:#444746}.auth-footer span:last-child{color:#6c7177}.viewer{max-width:970px;margin:36px auto;padding:0 24px}.viewer-top{display:flex;align-items:center;gap:15px;margin-bottom:24px}.viewer-top h1{font-size:20px;font-weight:400}.paper{background:white;min-height:500px;max-width:660px;margin:auto;padding:65px 55px;box-shadow:0 2px 8px #dfe3ea;text-align:center}.paper h2{font-size:27px;font-weight:400}.paper .doc-icon{display:inline-block;margin:35px}.paper p{color:#5f6368}.generic{max-width:1000px;margin:40px auto;padding:0 24px}.generic h1{font-size:32px;font-weight:400}.card{background:white;border:1px solid #e0e3e7;padding:24px;border-radius:16px;margin:18px 0}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:20px}.otp{font:40px monospace;letter-spacing:7px;color:#0b57d0}code{overflow-wrap:anywhere}table{width:100%;border-collapse:collapse;background:white;font-size:13px}td,th{text-align:left;padding:12px;border-bottom:1px solid #e0e3e7}small{color:#5f6368}.ok{color:#137333}.generic .button{margin:8px 10px 8px 0}.generic form{margin:18px 0}@media(max-width:760px){.mail-layout{grid-template-columns:1fr;padding:0 10px 15px}.mail-layout aside{display:none}.brand{min-width:0;font-size:22px}.search{display:none}.topbar{padding:0 18px;gap:14px}.message{padding:24px 18px}.subject{margin-left:0;font-size:21px}.sender .time{display:none}.share-card{padding:23px}.auth-wrap{margin:30px auto}.auth-card{padding:28px}.auth-grid{grid-template-columns:1fr;gap:25px}.auth-grid h1{font-size:30px}.training{padding:8px 12px}.training a{display:block;margin:3px 0 0}.paper{padding:35px 20px}.toolbar{gap:20px}}
'''
WORD = '<div class="g-word" aria-label="Google mockup"><span>G</span><span>o</span><span>o</span><span>g</span><span>l</span><span>e</span></div>'
BANNER = '<div class="training"><strong>TRAINING DEMO</strong> · Google-inspired mockup · Fictional account only · Not affiliated with Google<a href="http://localhost:8765/console">Presenter console</a></div>'

def document(title, body):
    return '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+html.escape(title)+' | Training demo</title><style>'+CSS+'</style></head><body>'+BANNER+body+'</body></html>'

def render(title, body):
    if title == 'A document was shared with you':
        return document(title, '''<div class="topbar"><span class="hamb" aria-hidden="true">☰</span><div class="brand"><span class="mailmark" aria-hidden="true">M</span>Gmail <small style="font-size:11px">MOCKUP</small></div><div class="search">⌕ &nbsp; Search mail <small style="float:right">Demo inbox</small></div><div class="topright"><span aria-hidden="true">⚙</span><div class="avatar">S</div></div></div><div class="mail-layout"><aside aria-label="Illustrative inbox sidebar"><div class="compose">✎ &nbsp; Compose</div><a class="folder active" href="/email">▣ &nbsp; Inbox <b>1</b></a><div class="folder">☆ &nbsp; Starred</div><div class="folder">◷ &nbsp; Snoozed</div><div class="folder">➤ &nbsp; Sent</div><div class="folder">▤ &nbsp; Drafts</div><div class="labels">Labels <span style="float:right">+</span></div><div class="folder">◇ &nbsp; Class project</div><p class="smallprint" style="padding:0 18px">Sidebar and search are visual mockups.</p></aside><main class="mailpane"><div class="toolbar"><a href="/email" aria-label="Back to demo inbox">←</a><span aria-hidden="true">▣</span><span aria-hidden="true">!</span><span aria-hidden="true">♧</span><span aria-hidden="true">⋮</span><span class="right">1 of 1</span></div><article class="message"><h1 class="subject">Jordan Example shared “Project Aurora”<span class="pill">Inbox</span></h1><div class="sender"><div class="avatar" style="background:#188038">J</div><div><strong>Jordan Example</strong> <small>&lt;jordan@example.test&gt;</small><br><small>to student@example.test</small></div><span class="time">9:41 AM &nbsp; ☆</span></div><div class="email-body"><div class="share-card"><h2>Jordan shared a document</h2><p>Hi Student,</p><p>Please review the updated project budget before our meeting.</p><div class="file-row"><span class="doc-icon">DOC</span><div><strong>Project Aurora</strong><br><small class="muted">Internal planning · Shared document</small></div></div><a class="button" href="/document">Open shared document</a><p class="smallprint">This fictional message is part of a local security-awareness demonstration. No email was sent.</p></div><span class="reply">↶ &nbsp; Reply</span></div></article></main></div>''')
    if title in ('Sign in to Example Workspace','Verify your identity'):
        is_otp = title == 'Verify your identity'
        # Reuse the existing server-generated form and CSRF/challenge fields verbatim.
        start = body.index('<form')
        end = body.index('</form>',start)+len('</form>')
        fields = body[start:end]
        err_start = body.find('<p class="error">')
        error = body[err_start:body.index('</p>',err_start)+4] if err_start>=0 else ''
        heading = '2-Step Verification' if is_otp else 'Sign in'
        intro = 'Confirm it’s you to continue to the shared document.' if is_otp else 'Use your training account to continue to the shared document.'
        hint = 'Use the current six-digit code from the presenter console.' if is_otp else 'Demo account: student@example.test<br>Demo password: <code>DemoOnly!42</code>'
        return document(heading, '<main class="auth-wrap"><section class="auth-card">'+WORD+'<div class="auth-grid"><div><h1>'+heading+'</h1><p>'+intro+'</p><span class="account">◉ &nbsp; student@example.test</span><p class="demo-hint">Local training simulation. This is not a Google account sign-in.</p></div><div class="auth-fields">'+error+fields+'<p class="demo-hint">'+hint+'</p></div></div></section><footer class="auth-footer"><span>English (United States)</span><span>Session Lab · Offline mockup</span></footer></main>')
    if title == 'Project Aurora.pdf':
        return document(title, '<main class="viewer"><div class="viewer-top"><a href="/email" aria-label="Back to email">←</a><span class="doc-icon">DOC</span><h1>Project Aurora.pdf</h1><span class="pill">Training document</span></div><section class="paper"><p>SHARED WITH YOU</p><span class="doc-icon">DOC</span><h2>Project Aurora</h2><p>Internal planning document · 1 page</p><hr style="border:0;border-top:1px solid #dadce0;margin:35px 0"><h3>Sign in to view this document</h3><p>Continue using the fictional account supplied for this demo.</p><a class="button" href="/login">View document</a></section></main>')
    return document(title,'<main class="generic"><h1>'+html.escape(title)+'</h1>'+body+'<p class="muted">Local classroom simulation · Fictional data only</p></main>')
